from typing import List

class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        memo = {}

        def dfs(i: int, rem: int) -> bool:
            if rem == 0:
                return True
            if i == len(nums) or rem < 0:
                return False
            key = (i, rem)
            if key not in memo:
                memo[key] = dfs(i + 1, rem - nums[i]) or dfs(i + 1, rem)
            return memo[key]

        return dfs(0, target)

